<script setup lang="ts">
import { ui } from "../ui"
import { computed,ref,watch,onMounted,onUnmounted } from 'vue'
import { useRoute,useRouter,onBeforeRouteLeave } from 'vue-router'
import { ChevronDownIcon } from '@heroicons/vue/24/outline'
import { api,bootstrap,notify } from '../composables/api'
import { currentDefinition,definitionKey,useCollaborationAction } from '../composables/collaboration'
import type { SavedView,ViewIndex,ViewPreferences } from '../types'
import ViewPreferencesDialog from './ViewPreferencesDialog.vue'
const route=useRoute(),router=useRouter(),perform=useCollaborationAction(),picker=ref<HTMLDetailsElement|null>(null),pickerPanel=ref<HTMLDivElement|null>(null)
function closePicker(restoreFocus=false){if(picker.value){picker.value.open=false;if(restoreFocus)picker.value.querySelector<HTMLElement>('summary')?.focus()}}
function outsidePicker(event:PointerEvent){if(event.target instanceof Node&&!picker.value?.contains(event.target))closePicker()}
onMounted(()=>document.addEventListener('pointerdown',outsidePicker,true));onUnmounted(()=>document.removeEventListener('pointerdown',outsidePicker,true))
const index=ref<ViewIndex|null>(null),selected=ref<SavedView|null>(null),prefs=ref<ViewPreferences>({version:0,shortcuts:[],default_view_ref:null,labels:{}}),error=ref(''),saving=ref(false),loading=ref(false),preferencesDialog=ref<InstanceType<typeof ViewPreferencesDialog>|null>(null)
const mode=ref<'create'|'copy'|'update'|'rename'|'repair'|null>(null),name=ref(''),visibility=ref<'personal'|'shared'>('personal'),formBaseline=ref(''),deleteConfirm=ref(false)
const known=ref<Record<string,SavedView>>({});let selectionGeneration=0,disposed=false
const definition=computed(()=>currentDefinition(route.query)),modified=computed(()=>!!selected.value&&definitionKey(definition.value)!==definitionKey(selected.value.definition))
const selectedRef=computed(()=>typeof route.query.view==='string'?route.query.view:route.query.assignee==='me'?'builtin:assigned_to_me':['unresolved','resolved','ignored','snoozed'].includes(String(route.query.status??'unresolved'))?'builtin:'+String(route.query.status??'unresolved'):'current')
const prefDirty=computed(()=>preferencesDialog.value?.dirty??false),editorDirty=computed(()=>mode.value!==null&&formBaseline.value!==JSON.stringify([name.value,visibility.value]))
function mayLeave(){return (!editorDirty.value&&!prefDirty.value)||window.confirm('Discard unsaved view changes?')}
onBeforeRouteLeave(mayLeave)
const unload=(e:BeforeUnloadEvent)=>{if(editorDirty.value||prefDirty.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>{window.addEventListener('beforeunload',unload);initialize()});onUnmounted(()=>{disposed=true;selectionGeneration++;window.removeEventListener('beforeunload',unload)})
function title(id:string){return known.value[id]?.name??prefs.value.labels?.[id]??(id.startsWith('builtin:')?id.slice(8).replaceAll('_',' '):'Saved view')}
async function list(page=1){try{const result=await api<ViewIndex>('/views?page='+page);if(disposed)return;index.value=result;for(const v of result.items)known.value[v.id]=v}catch(e){error.value=e instanceof Error?e.message:'Views could not be loaded.'}}
async function loadPreferences(){const p=await api<ViewPreferences>('/view-preferences');if(disposed)return;prefs.value=p}
async function loadSelected(){const id=route.query.view,generation=++selectionGeneration;if(typeof id!=='string'){selected.value=null;return}try{const view=await api<SavedView>('/views/'+id);if(disposed||generation!==selectionGeneration)return;selected.value=view;known.value[view.id]=view}catch(e){if(generation===selectionGeneration){selected.value=null;error.value=e instanceof Error?e.message:'This view is unavailable.'}}}
watch(()=>route.query.view,async()=>{deleteConfirm.value=false;await loadSelected();await hydrateShortLink()})
async function initialize(){loading.value=true;try{await Promise.all([list(),loadPreferences()]);await loadSelected();await hydrateShortLink();if(!Object.keys(route.query).length&&prefs.value.default_view_ref)await apply(prefs.value.default_view_ref)}catch(e){error.value=e instanceof Error?e.message:'View preferences could not be loaded.'}finally{loading.value=false}}
async function hydrateShortLink(){if(selected.value?.state==='ready'&&route.query.view&&!Object.keys(route.query).some(k=>!['view','page','per_page'].includes(k)))await apply(selected.value.id,true)}
async function apply(id:string,preservePage=false){closePicker();if(id==='current')return;if(!mayLeave())return;mode.value=null;error.value='';if(id.startsWith('builtin:')){const state=id.slice(8);await router.replace({query:state==='assigned_to_me'?{status:'unresolved',assignee:'me',range:'24h',sort:'last_seen'}:{status:state,range:'24h',sort:'last_seen'}});return}
 try{const v=known.value[id]??await api<SavedView>('/views/'+id);if(v.state!=='ready'){selected.value=v;known.value[id]=v;await router.replace({query:{view:id}});error.value=v.reason??'Repair this view before applying it.';return}const q:Record<string,string>={view:id,sort:v.definition.sort,range:v.definition.range,status:String(v.definition.filters.status??'unresolved')};for(const[k,value]of Object.entries(v.definition.filters))q[k]=typeof value==='boolean'?(value?'1':'0'):value;if(preservePage){for(const key of ['page','per_page'])if(typeof route.query[key]==='string')q[key]=route.query[key] as string}await router.replace({query:q})}catch(e){error.value=e instanceof Error?e.message:'View unavailable.'}}
function open(next:typeof mode.value){closePicker();if(editorDirty.value&&!window.confirm('Discard the current view-name draft?'))return;mode.value=next;deleteConfirm.value=false;name.value=next==='create'?'':next==='copy'?(selected.value?.name.slice(0,74)??'Current filters')+' copy':selected.value?.name??'';visibility.value=next==='create'||next==='copy'?'personal':selected.value?.visibility??'personal';formBaseline.value=JSON.stringify([name.value,visibility.value]);error.value=''}
function close(){if(editorDirty.value&&!window.confirm('Discard the unsaved view-name draft?'))return;mode.value=null}
async function save(){if(!name.value.trim()||Array.from(name.value).length>80){error.value='Enter a name of 1–80 characters.';return}saving.value=true;error.value='';try{const existing=selected.value;const isNew=mode.value==='create'||mode.value==='copy';const renaming=mode.value==='rename';const value=renaming?{name:name.value,version:existing!.version}:{...definition.value,name:name.value,visibility:visibility.value,...(!isNew?{version:existing!.version}:{})};const result=await perform<{id:string}>('/views'+(isNew?'':'/'+existing!.id)+(renaming?'/name':''),isNew?'POST':'PATCH',value);mode.value=null;notify(renaming?'View renamed.':'View saved.');await list(index.value?.page??1);await loadSelected();const view=await api<SavedView>('/views/'+result.id);known.value[view.id]=view;if(!renaming)await apply(view.id)}catch(e){error.value=e instanceof Error?e.message:'View could not be saved.'}finally{saving.value=false}}
async function reloadCurrent(){if(!mayLeave())return;mode.value=null;await loadSelected()}
async function remove(){if(!selected.value)return;saving.value=true;error.value='';try{await perform('/views/'+selected.value.id,'DELETE',{version:selected.value.version});deleteConfirm.value=false;mode.value=null;notify('Saved view removed. Errors were not changed.');await router.replace({query:{status:'unresolved'}});await Promise.all([list(),loadPreferences()])}catch(e){error.value=e instanceof Error?e.message:'The view could not be removed.'}finally{saving.value=false}}
function showPreferences(){closePicker();preferencesDialog.value?.show()}
function preferencesSaved(value:ViewPreferences){prefs.value=value}
</script>
<template><section :class="ui('$all', '$section', 'saved-views')" aria-label="Saved views"><div :class="ui('$all', '$div', 'saved-view-toolbar')"><details ref="picker" :class="ui('$all', '$details', 'saved-view-picker')" @keydown.esc.stop.prevent="closePicker(true)"><summary :class="ui('$all', '$summary', 'button')"><span :class="ui('$all', '$span')">{{selected?.name??'Saved views'}}</span><ChevronDownIcon :class="ui('$all', '$svg')" aria-hidden="true"/></summary><div ref="pickerPanel" :class="ui('$all', '$div', 'saved-view-picker-panel')"><label :class="ui('$all', '$label', 'saved-view-select')">Choose a view<select :class="ui('$all', '$select')" :value="selectedRef" :disabled="loading||saving" @change="apply(($event.target as HTMLSelectElement).value)"><option :class="ui('$all', '$option')" v-if="selectedRef==='current'" value="current">Current filters</option><option :class="ui('$all', '$option')" v-if="route.query.view&&!selected" :value="String(route.query.view)">Unavailable saved view</option><optgroup :class="ui('$all', '$optgroup')" label="Built-in"><option :class="ui('$all', '$option')" v-for="id in index?.builtins??['builtin:unresolved','builtin:resolved','builtin:ignored','builtin:snoozed']" :key="id" :value="id">{{title(id)}}</option></optgroup><optgroup :class="ui('$all', '$optgroup')" label="Saved views"><option :class="ui('$all', '$option')" v-if="selected&&!index?.items.some(v=>v.id===selected!.id)" :value="selected.id">{{selected.name}} · {{selected.visibility}}</option><option :class="ui('$all', '$option')" v-for="v in index?.items" :key="v.id" :value="v.id">{{v.name}} · {{v.visibility}}{{v.state==='needs_repair'?' · Needs repair':''}}</option></optgroup></select></label><span v-if="selected" :class="ui('$all', '$span', 'badge')">{{selected.visibility}}</span><span v-if="selected&&modified&&selected.state==='ready'" :class="ui('$all', '$span', 'unsaved')">Modified</span><button v-if="selected?.can_edit&&modified&&selected.state==='ready'" :class="ui('$all', '$button', 'button')" :disabled="saving" @click="open('update')">Update view</button><button v-if="selected" :class="ui('$all', '$button', 'button')" :disabled="saving" @click="open('copy')">Save a copy</button><button :class="ui('$all', '$button', 'text-link')" :disabled="loading||saving" @click="showPreferences">View preferences</button><nav v-if="prefs.shortcuts.some(s=>s.favorite)" :class="ui('$all', '$nav', 'view-shortcuts')" aria-label="Favorite views"><button v-for="s in prefs.shortcuts.filter(s=>s.favorite)" :key="s.ref" :class="ui('$all', '$button', 'button')" :disabled="saving" @click="apply(s.ref)">{{title(s.ref)}}</button></nav></div></details><button :class="ui('$all', '$button', 'button primary')" :disabled="saving" @click="open('create')">Save view</button><span v-if="selected&&modified&&selected.state==='ready'" :class="ui('$all', '$span', 'unsaved')">Modified</span></div><p v-if="selected" :class="ui('$all', '$p', 'help')">Owned by {{selected.owner}}. {{selected.visibility==='personal'?'Only you can open this view.':'Visible to authorized dashboard users.'}}<span v-if="selected.can_edit" :class="ui('$all', '$span', 'view-management')"> <button :class="ui('$all', '$button', 'text-link')" @click="open('rename')">Rename</button> · <button :class="ui('$all', '$button', 'text-link danger-link')" @click="deleteConfirm=true">Delete view</button></span></p><div v-if="selected?.state==='needs_repair'" :class="ui('$all', '$div', 'notice warning')"><div :class="ui('$all', '$div')"><strong :class="ui('$all', '$strong')">This view needs repair</strong><p :class="ui('$all', '$p')">{{selected.reason}}</p><button v-if="selected.can_edit" :class="ui('$all', '$button', 'button')" @click="open('repair')">Replace with current supported filters</button><button :class="ui('$all', '$button', 'button')" @click="router.replace({query:{status:'unresolved'}})">Clear view</button></div></div><div v-if="error" :class="ui('$all', '$div', 'notice danger')" role="alert"><div :class="ui('$all', '$div')"><p :class="ui('$all', '$p')">{{error}}</p><button v-if="selected" :class="ui('$all', '$button', 'button')" @click="reloadCurrent">Reload current view</button><button v-else :class="ui('$all', '$button', 'button')" @click="initialize">Try again</button></div></div><form v-if="mode" :class="ui('$all', '$form', 'saved-view-editor')" @submit.prevent="save"><h3 :class="ui('$all', '$h3')">{{mode==='rename'?'Rename view':mode==='update'?'Update saved definition':mode==='repair'?'Repair view with current filters':mode==='copy'?'Save a personal copy':'Save current inbox filters'}}</h3><label :class="ui('$all', '$label', 'field')">View name <small :class="ui('$all', '$small')">{{Array.from(name).length}} / 80 characters</small><input :class="ui('$all', '$input')" v-model="name" required :disabled="saving"></label><label v-if="mode!=='rename'" :class="ui('$all', '$label', 'field')">Visibility<select :class="ui('$all', '$select')" v-model="visibility" :disabled="saving||!!selected&&!selected.own&&!['create','copy'].includes(mode)"><option :class="ui('$all', '$option')" value="personal">Personal · only you</option><option :class="ui('$all', '$option')" value="shared" :disabled="!bootstrap?.capabilities.operate&&!bootstrap?.capabilities.manage">Shared · dashboard users</option></select></label><p :class="ui('$all', '$p', 'help')">{{mode==='rename'?'Renaming preserves the saved filters.':'Stores permitted filters, sort and relative range—not a frozen result set. Existing definitions are only replaced when you save.'}}</p><div :class="ui('$all', '$div', 'inline-actions')"><button :class="ui('$all', '$button', 'button primary')" :disabled="saving">{{saving?'Saving…':mode==='rename'?'Rename view':'Save definition'}}</button><button type="button" :class="ui('$all', '$button', 'button')" :disabled="saving" @click="close">Cancel</button></div></form><div v-if="deleteConfirm&&selected" :class="ui('$all', '$div', 'notice warning')"><div :class="ui('$all', '$div')"><p :class="ui('$all', '$p')">Delete “{{selected.name}}”? Its definition and shortcuts become unavailable. Error data is retained.</p><div :class="ui('$all', '$div', 'inline-actions')"><button :class="ui('$all', '$button', 'button')" :disabled="saving" @click="remove">Confirm delete view</button><button :class="ui('$all', '$button', 'button')" :disabled="saving" @click="deleteConfirm=false">Keep view</button></div></div></div><ViewPreferencesDialog ref="preferencesDialog" :preferences="prefs" :views="Object.values(known)" :builtins="index?.builtins??['builtin:unresolved','builtin:resolved','builtin:ignored','builtin:snoozed']" @saved="preferencesSaved" @closed="closePicker(true)"/><div v-if="index&&index.last_page>1" :class="ui('$all', '$div', 'pagination')"><span :class="ui('$all', '$span')">{{index.total}} saved views · page {{index.page}} of {{index.last_page}}</span><button :class="ui('$all', '$button', 'button')" :disabled="index.page<=1" @click="list(index.page-1)">Previous views</button><button :class="ui('$all', '$button', 'button')" :disabled="index.page>=index.last_page" @click="list(index.page+1)">More views</button></div></section></template>
